vol_sfx:["אפקטים (יריות, פיצוצים, קולות)","Effects (shots, explosions, voices)","المؤثرات (طلقات، انفجارات، أصوات)","Эффекты (выстрелы, взрывы, голоса)","Efectos (disparos, explosiones, voces)"],
