function applyLang(id){
  LANG=LANGS.some(l=>l.id===id)?id:'he'; LI=LANGS.findIndex(l=>l.id===LANG);
  const L=LANGS[LI]; document.documentElement.lang=LANG; document.documentElement.dir=L.dir; document.title=T('title');
  document.querySelectorAll('[data-i]').forEach(e=>{e.innerHTML=T(e.dataset.i);});
}
